def kill_job(server: str, pid: str, reason: str = "", *, account: str | None = None) -> ToolResult:
    """Kill a running training job.

    Attempts graceful SIGTERM first, then SIGKILL after 10s. Also kills
    the tmux session if pid matches a session name.

    Args:
        server: Server name from resources.yaml.
        pid: Process ID or tmux session name.
        reason: Human-readable reason for killing.
        account: SSH account (user) on the server. None = default account.

    Returns:
        ToolResult indicating success/failure.
    """
    t0 = time.monotonic()

    # pid may be numeric PID or exp_id (tmux session name)
    is_numeric = _RE_PID.match(pid.strip())
    try:
        if is_numeric:
            pid = _validate_pid(pid)
        else:
            pid = _validate_identifier(pid, "pid/session_name")
    except ValueError as e:
        return ToolResult(success=False, error=str(e), metadata={"elapsed_seconds": 0})

    try:
        conn = _get_connection(server, account)

        from core.tools.execution_backends import get_execution_backend

                    )
